settings.custom_liquid:
{% assign specs = product.metafields.custom.specification.value | parse_json %}

{% if specs %}
  <table class="tp-specification-table">
    {% if specs.acea %}
      <tr>
        <td><strong>ACEA specification</strong></td>
        <td>{{ specs.acea }}</td>
      </tr>
    {% endif %}
    {% if specs.api %}
      <tr>
        <td><strong>API specification</strong></td>
        <td>{{ specs.api }}</td>
      </tr>
    {% endif %}
    {% if specs.manufacturer_approval_1 %}
      <tr>
        <td><strong>Manufacturer Approval</strong></td>
        <td>{{ specs.manufacturer_approval_1 }}</td>
      </tr>
    {% endif %}
    {% if specs.manufacturer_approval_2 %}
      <tr>
        <td><strong>Manufacturer Approval</strong></td>
        <td>{{ specs.manufacturer_approval_2 }}</td>
      </tr>
    {% endif %}
    {% if specs.manufacturer_approval_3 %}
      <tr>
        <td><strong>Manufacturer Approval</strong></td>
        <td>{{ specs.manufacturer_approval_3 }}</td>
      </tr>
    {% endif %}
    {% if specs.manufacturer_approval_4 %}
      <tr>
        <td><strong>Manufacturer Approval</strong></td>
        <td>{{ specs.manufacturer_approval_4 }}</td>
      </tr>
    {% endif %}
    {% if specs.sae %}
      <tr>
        <td><strong>SAE viscosity class</strong></td>
        <td>{{ specs.sae }}</td>
      </tr>
    {% endif %}
  </table>
{% endif %}

{% assign datasheets = product.metafields.custom.product_data_sheet.value | parse_json %}

{% if datasheets.size > 0 %}
   <div class="tp-pdf-list">
    {% for sheet in datasheets %}
      <div>
        <img src="https://cdn.shopify.com/s/files/1/0594/6382/7614/files/pdf.avif?v=1748002674" alt="PDF icon" width="24" height="24" />
        <a href="{{ sheet.url }}" target="_blank" rel="noopener">
          {{ sheet.name }}
        </a>
      </div>
    {% endfor %}
  </div>
{% endif %}
